#!/usr/bin/env python3
from pathlib import Path
import subprocess

ROOT = Path.cwd()
EXPECTED_BRANCH = "feat/repository-baseline-consolidation-cleanup"
REFERENCE_SHA = "3802cef33e676a810e0bb12676ba84fe6e2a74b5"
SELF = Path(__file__).name

def run(*args, check=True):
    return subprocess.run(
        args, cwd=ROOT, check=check, text=True,
        stdout=subprocess.PIPE, stderr=subprocess.PIPE
    )

def require(condition, message):
    if not condition:
        raise RuntimeError(message)

def read(relative):
    path = ROOT / relative
    require(path.is_file(), f"Missing expected file: {relative}")
    return path.read_text(encoding="utf-8")

def write_new(relative, content):
    path = ROOT / relative
    require(not path.exists(), f"Refusing to overwrite existing file: {relative}")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8", newline="\n")
    print(f"CREATE  {relative}")

def replace_once(relative, old, new):
    path = ROOT / relative
    current = read(relative)
    count = current.count(old)
    require(count == 1, f"Expected one marker in {relative}; found {count}")
    path.write_text(current.replace(old, new, 1), encoding="utf-8", newline="\n")
    print(f"UPDATE  {relative}")

require((ROOT / ".git").exists(), "Run from repository root.")
branch = run("git", "branch", "--show-current").stdout.strip()
require(branch == EXPECTED_BRANCH, f"Unexpected branch: {branch}")
require(
    run("git", "merge-base", "--is-ancestor", REFERENCE_SHA, "HEAD", check=False).returncode == 0,
    f"Reference SHA {REFERENCE_SHA} is not an ancestor of HEAD."
)
fingerprint = read(
    "backend/payment/src/main/java/com/sixpay/payment/infrastructure/idempotency/PaymentOtpIdempotencyFingerprint.java"
)
require(
    "HmacSHA256" in fingerprint
    and "SIXPAY_PAYMENT_CONFIRMATION_VERIFY_V1" in fingerprint
    and "Arrays.fill(otpBytes, (byte) 0)" in fingerprint,
    "Existing PaymentOtpIdempotencyFingerprint baseline not recognized."
)

write_new('backend/payment/src/main/java/com/sixpay/payment/application/port/output/idempotency/PaymentConfirmationIdempotencyPort.java', 'package com.sixpay.payment.application.port.output.idempotency;\n\nimport com.sixpay.payment.application.port.output.banking.PaymentConfirmationBankResult;\nimport com.sixpay.payment.domain.model.ConfirmationChallengeReference;\nimport com.sixpay.payment.domain.model.IdempotencyKey;\nimport com.sixpay.payment.domain.model.PaymentId;\nimport com.sixpay.payment.domain.model.PublicPaymentReference;\n\nimport java.util.function.Supplier;\n\npublic interface PaymentConfirmationIdempotencyPort {\n\n    PaymentConfirmationBankResult executeCreate(\n            PaymentId paymentId,\n            PublicPaymentReference paymentReference,\n            IdempotencyKey idempotencyKey,\n            Supplier<PaymentConfirmationBankResult> newRequest,\n            Supplier<PaymentConfirmationBankResult> recovery\n    );\n\n    PaymentConfirmationBankResult executeVerify(\n            PaymentId paymentId,\n            PublicPaymentReference paymentReference,\n            IdempotencyKey idempotencyKey,\n            char[] otp,\n            Supplier<PaymentConfirmationBankResult> newRequest\n    );\n\n    PaymentConfirmationBankResult executeReplace(\n            PaymentId paymentId,\n            PublicPaymentReference paymentReference,\n            ConfirmationChallengeReference challengeReference,\n            IdempotencyKey idempotencyKey,\n            Supplier<PaymentConfirmationBankResult> newRequest,\n            Supplier<PaymentConfirmationBankResult> recovery\n    );\n}\n')
write_new('backend/payment/src/main/java/com/sixpay/payment/infrastructure/idempotency/PaymentOtpIdempotencyFingerprintSet.java', 'package com.sixpay.payment.infrastructure.idempotency;\n\nimport java.util.LinkedHashSet;\nimport java.util.List;\nimport java.util.Objects;\n\npublic final class PaymentOtpIdempotencyFingerprintSet {\n\n    private final List<PaymentOtpIdempotencyFingerprint> fingerprints;\n\n    public PaymentOtpIdempotencyFingerprintSet(\n            List<PaymentOtpIdempotencyFingerprint> fingerprints\n    ) {\n        if (fingerprints == null || fingerprints.isEmpty()) {\n            throw new IllegalArgumentException(\n                    "At least one OTP idempotency fingerprint is required"\n            );\n        }\n\n        this.fingerprints = List.copyOf(\n                fingerprints.stream()\n                        .map(value -> Objects.requireNonNull(\n                                value,\n                                "OTP idempotency fingerprint"\n                        ))\n                        .toList()\n        );\n    }\n\n    public List<String> candidates(\n            String paymentReference,\n            char[] otp\n    ) {\n        Objects.requireNonNull(otp, "OTP");\n        if (otp.length == 0) {\n            throw new IllegalArgumentException("OTP must not be empty");\n        }\n\n        String transientOtp = new String(otp);\n        try {\n            LinkedHashSet<String> values = new LinkedHashSet<>();\n            for (PaymentOtpIdempotencyFingerprint fingerprint\n                    : fingerprints) {\n                values.add(\n                        fingerprint.fingerprint(\n                                paymentReference,\n                                transientOtp\n                        )\n                );\n            }\n            return List.copyOf(values);\n        } finally {\n            transientOtp = null;\n        }\n    }\n}\n')
write_new('backend/payment/src/main/java/com/sixpay/payment/infrastructure/idempotency/PaymentConfirmationCanonicalizer.java', 'package com.sixpay.payment.infrastructure.idempotency;\n\nimport com.sixpay.payment.domain.model.ConfirmationChallengeReference;\nimport com.sixpay.payment.domain.model.PaymentId;\nimport com.sixpay.payment.domain.model.PublicPaymentReference;\nimport org.springframework.stereotype.Component;\n\nimport java.util.Objects;\n\n@Component\npublic final class PaymentConfirmationCanonicalizer {\n\n    private static final String VERSION = "v1";\n\n    public String create(\n            PaymentId paymentId,\n            PublicPaymentReference paymentReference\n    ) {\n        return String.join(\n                "|",\n                VERSION,\n                "CREATE",\n                Objects.requireNonNull(paymentId, "Payment ID").toString(),\n                Objects.requireNonNull(\n                        paymentReference,\n                        "Payment reference"\n                ).value()\n        );\n    }\n\n    public String replace(\n            PaymentId paymentId,\n            PublicPaymentReference paymentReference,\n            ConfirmationChallengeReference challengeReference\n    ) {\n        return String.join(\n                "|",\n                VERSION,\n                "REPLACE",\n                Objects.requireNonNull(paymentId, "Payment ID").toString(),\n                Objects.requireNonNull(\n                        paymentReference,\n                        "Payment reference"\n                ).value(),\n                Objects.requireNonNull(\n                        challengeReference,\n                        "Challenge reference"\n                ).value()\n        );\n    }\n}\n')
write_new('backend/payment/src/main/java/com/sixpay/payment/infrastructure/idempotency/PaymentConfirmationReplayCodec.java', 'package com.sixpay.payment.infrastructure.idempotency;\n\nimport com.sixpay.payment.application.port.output.banking.PaymentConfirmationBankResult;\nimport com.sixpay.payment.domain.model.ConfirmationBusinessCode;\nimport com.sixpay.payment.domain.model.ConfirmationChallengeReference;\nimport com.sixpay.payment.domain.model.ConfirmationChallengeStatus;\nimport com.sixpay.payment.domain.model.ConfirmationDeliveryChannel;\nimport org.springframework.stereotype.Component;\n\nimport java.nio.charset.StandardCharsets;\nimport java.time.Instant;\nimport java.util.Base64;\n\n@Component\npublic final class PaymentConfirmationReplayCodec {\n\n    private static final String VERSION = "v1";\n    private static final String NULL = "-";\n\n    public String encode(PaymentConfirmationBankResult result) {\n        return String.join(\n                "|",\n                VERSION,\n                encodeText(result.challengeReference().value()),\n                result.status().name(),\n                result.businessCode().name(),\n                result.deliveryChannel() == null\n                        ? NULL\n                        : result.deliveryChannel().name(),\n                encodeInstant(result.sentAt()),\n                encodeInstant(result.expiresAt()),\n                encodeInstant(result.verifiedAt())\n        );\n    }\n\n    public PaymentConfirmationBankResult decode(String payload) {\n        if (payload == null || payload.isBlank()) {\n            throw new IllegalArgumentException(\n                    "Payment confirmation replay payload is empty"\n            );\n        }\n\n        String[] values = payload.split("\\\\|", -1);\n        if (values.length != 8 || !VERSION.equals(values[0])) {\n            throw new IllegalArgumentException(\n                    "Unsupported Payment confirmation replay payload"\n            );\n        }\n\n        return new PaymentConfirmationBankResult(\n                new ConfirmationChallengeReference(\n                        decodeText(values[1])\n                ),\n                ConfirmationChallengeStatus.valueOf(values[2]),\n                ConfirmationBusinessCode.valueOf(values[3]),\n                NULL.equals(values[4])\n                        ? null\n                        : ConfirmationDeliveryChannel.valueOf(\n                                values[4]\n                        ),\n                decodeInstant(values[5]),\n                decodeInstant(values[6]),\n                decodeInstant(values[7])\n        );\n    }\n\n    private static String encodeInstant(Instant value) {\n        return value == null ? NULL : value.toString();\n    }\n\n    private static Instant decodeInstant(String value) {\n        return NULL.equals(value) ? null : Instant.parse(value);\n    }\n\n    private static String encodeText(String value) {\n        return Base64.getUrlEncoder()\n                .withoutPadding()\n                .encodeToString(\n                        value.getBytes(StandardCharsets.UTF_8)\n                );\n    }\n\n    private static String decodeText(String value) {\n        return new String(\n                Base64.getUrlDecoder().decode(value),\n                StandardCharsets.UTF_8\n        );\n    }\n}\n')
write_new('backend/payment/src/main/java/com/sixpay/payment/infrastructure/idempotency/PaymentConfirmationIdempotencyTransactions.java', 'package com.sixpay.payment.infrastructure.idempotency;\n\nimport org.springframework.stereotype.Component;\nimport org.springframework.transaction.annotation.Propagation;\nimport org.springframework.transaction.annotation.Transactional;\n\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Objects;\nimport java.util.UUID;\n\n@Component\npublic class PaymentConfirmationIdempotencyTransactions {\n\n    private final PaymentIdempotencyConcurrencyCoordinator coordinator;\n    private final PaymentIdempotencyReplayStore replayStore;\n\n    public PaymentConfirmationIdempotencyTransactions(\n            PaymentIdempotencyConcurrencyCoordinator coordinator,\n            PaymentIdempotencyReplayStore replayStore\n    ) {\n        this.coordinator = Objects.requireNonNull(\n                coordinator,\n                "Idempotency concurrency coordinator"\n        );\n        this.replayStore = Objects.requireNonNull(\n                replayStore,\n                "Idempotency replay store"\n        );\n    }\n\n    @Transactional(propagation = Propagation.REQUIRES_NEW)\n    public BeginResult begin(\n            String operation,\n            String idempotencyKey,\n            String preferredHash,\n            List<String> acceptedHashes,\n            Instant startedAt\n    ) {\n        return coordinator.executeLocked(\n                operation,\n                idempotencyKey,\n                () -> {\n                    PaymentIdempotencyReplayStore.MatchingBeginResult result =\n                            replayStore.beginMatchingHashes(\n                                    operation,\n                                    idempotencyKey,\n                                    preferredHash,\n                                    acceptedHashes,\n                                    startedAt\n                            );\n                    return new BeginResult(\n                            result.decision(),\n                            result.requestHash()\n                    );\n                }\n        );\n    }\n\n    @Transactional(propagation = Propagation.REQUIRES_NEW)\n    public void complete(\n            String operation,\n            String idempotencyKey,\n            String requestHash,\n            UUID paymentId,\n            String responseStatus,\n            String responsePayload,\n            Instant completedAt\n    ) {\n        replayStore.complete(\n                operation,\n                idempotencyKey,\n                requestHash,\n                paymentId,\n                responseStatus,\n                responsePayload,\n                completedAt\n        );\n    }\n\n    @Transactional(propagation = Propagation.REQUIRES_NEW)\n    public void markOutcomeUnknown(\n            String operation,\n            String idempotencyKey,\n            String requestHash,\n            UUID paymentId,\n            String recoveryReference,\n            String recoveryReason,\n            Instant unknownOutcomeAt\n    ) {\n        replayStore.markOutcomeUnknown(\n                operation,\n                idempotencyKey,\n                requestHash,\n                paymentId,\n                recoveryReference,\n                recoveryReason,\n                unknownOutcomeAt\n        );\n    }\n\n    @Transactional(propagation = Propagation.REQUIRES_NEW)\n    public void fail(\n            String operation,\n            String idempotencyKey,\n            String requestHash,\n            String reason,\n            Instant failedAt\n    ) {\n        replayStore.fail(\n                operation,\n                idempotencyKey,\n                requestHash,\n                reason,\n                failedAt\n        );\n    }\n\n    public record BeginResult(\n            PaymentIdempotencyDecision decision,\n            String requestHash\n    ) {\n        public BeginResult {\n            decision = Objects.requireNonNull(\n                    decision,\n                    "Idempotency decision"\n            );\n            if (requestHash == null\n                    || !requestHash.matches("^[0-9a-f]{64}$")) {\n                throw new IllegalArgumentException(\n                        "Effective request hash is invalid"\n                );\n            }\n        }\n    }\n}\n')
write_new('backend/payment/src/main/java/com/sixpay/payment/infrastructure/idempotency/PaymentConfirmationIdempotencyAdapter.java', 'package com.sixpay.payment.infrastructure.idempotency;\n\nimport com.sixpay.common.time.TimeProvider;\nimport com.sixpay.payment.application.port.output.banking.PaymentConfirmationBankResult;\nimport com.sixpay.payment.application.port.output.banking.PaymentConfirmationGateway;\nimport com.sixpay.payment.application.port.output.idempotency.PaymentConfirmationIdempotencyPort;\nimport com.sixpay.payment.domain.model.ConfirmationChallengeReference;\nimport com.sixpay.payment.domain.model.IdempotencyKey;\nimport com.sixpay.payment.domain.model.PaymentId;\nimport com.sixpay.payment.domain.model.PublicPaymentReference;\nimport org.springframework.boot.autoconfigure.condition.ConditionalOnBean;\nimport org.springframework.stereotype.Component;\n\nimport java.util.List;\nimport java.util.Objects;\nimport java.util.function.Supplier;\n\n@Component\n@ConditionalOnBean(PaymentOtpIdempotencyFingerprintSet.class)\npublic class PaymentConfirmationIdempotencyAdapter\n        implements PaymentConfirmationIdempotencyPort {\n\n    static final String CREATE_OPERATION =\n            "PAYMENT_CONFIRMATION_CREATE";\n    static final String VERIFY_OPERATION =\n            "PAYMENT_CONFIRMATION_VERIFY";\n    static final String REPLACE_OPERATION =\n            "PAYMENT_CONFIRMATION_REPLACE";\n\n    private final PaymentConfirmationCanonicalizer canonicalizer;\n    private final PaymentIdempotencyHasher hasher;\n    private final PaymentOtpIdempotencyFingerprintSet otpFingerprints;\n    private final PaymentConfirmationIdempotencyTransactions transactions;\n    private final PaymentConfirmationReplayCodec replayCodec;\n    private final TimeProvider timeProvider;\n\n    public PaymentConfirmationIdempotencyAdapter(\n            PaymentConfirmationCanonicalizer canonicalizer,\n            PaymentIdempotencyHasher hasher,\n            PaymentOtpIdempotencyFingerprintSet otpFingerprints,\n            PaymentConfirmationIdempotencyTransactions transactions,\n            PaymentConfirmationReplayCodec replayCodec,\n            TimeProvider timeProvider\n    ) {\n        this.canonicalizer = Objects.requireNonNull(canonicalizer);\n        this.hasher = Objects.requireNonNull(hasher);\n        this.otpFingerprints = Objects.requireNonNull(otpFingerprints);\n        this.transactions = Objects.requireNonNull(transactions);\n        this.replayCodec = Objects.requireNonNull(replayCodec);\n        this.timeProvider = Objects.requireNonNull(timeProvider);\n    }\n\n    @Override\n    public PaymentConfirmationBankResult executeCreate(\n            PaymentId paymentId,\n            PublicPaymentReference paymentReference,\n            IdempotencyKey idempotencyKey,\n            Supplier<PaymentConfirmationBankResult> newRequest,\n            Supplier<PaymentConfirmationBankResult> recovery\n    ) {\n        String requestHash = hasher.hash(\n                canonicalizer.create(paymentId, paymentReference)\n        );\n\n        return executeRecoverable(\n                CREATE_OPERATION,\n                paymentId,\n                idempotencyKey,\n                requestHash,\n                List.of(requestHash),\n                newRequest,\n                recovery\n        );\n    }\n\n    @Override\n    public PaymentConfirmationBankResult executeVerify(\n            PaymentId paymentId,\n            PublicPaymentReference paymentReference,\n            IdempotencyKey idempotencyKey,\n            char[] otp,\n            Supplier<PaymentConfirmationBankResult> newRequest\n    ) {\n        List<String> candidates =\n                otpFingerprints.candidates(\n                        paymentReference.value(),\n                        otp\n                );\n\n        PaymentConfirmationIdempotencyTransactions.BeginResult begin =\n                transactions.begin(\n                        VERIFY_OPERATION,\n                        idempotencyKey.value(),\n                        candidates.get(0),\n                        candidates,\n                        timeProvider.now()\n                );\n\n        return switch (begin.decision().kind()) {\n            case REPLAY ->\n                    replay(paymentId, begin.decision());\n\n            case IN_PROGRESS ->\n                    throw new IllegalStateException(\n                            "Payment confirmation verification is already in progress"\n                    );\n\n            case OUTCOME_UNKNOWN ->\n                    throw new IllegalStateException(\n                            "Verify idempotency must not enter OUTCOME_UNKNOWN"\n                    );\n\n            case NEW ->\n                    completeNew(\n                            VERIFY_OPERATION,\n                            paymentId,\n                            idempotencyKey.value(),\n                            begin.requestHash(),\n                            newRequest\n                    );\n        };\n    }\n\n    @Override\n    public PaymentConfirmationBankResult executeReplace(\n            PaymentId paymentId,\n            PublicPaymentReference paymentReference,\n            ConfirmationChallengeReference challengeReference,\n            IdempotencyKey idempotencyKey,\n            Supplier<PaymentConfirmationBankResult> newRequest,\n            Supplier<PaymentConfirmationBankResult> recovery\n    ) {\n        String requestHash = hasher.hash(\n                canonicalizer.replace(\n                        paymentId,\n                        paymentReference,\n                        challengeReference\n                )\n        );\n\n        return executeRecoverable(\n                REPLACE_OPERATION,\n                paymentId,\n                idempotencyKey,\n                requestHash,\n                List.of(requestHash),\n                newRequest,\n                recovery\n        );\n    }\n\n    private PaymentConfirmationBankResult executeRecoverable(\n            String operation,\n            PaymentId paymentId,\n            IdempotencyKey idempotencyKey,\n            String preferredHash,\n            List<String> acceptedHashes,\n            Supplier<PaymentConfirmationBankResult> newRequest,\n            Supplier<PaymentConfirmationBankResult> recovery\n    ) {\n        PaymentConfirmationIdempotencyTransactions.BeginResult begin =\n                transactions.begin(\n                        operation,\n                        idempotencyKey.value(),\n                        preferredHash,\n                        acceptedHashes,\n                        timeProvider.now()\n                );\n\n        return switch (begin.decision().kind()) {\n            case REPLAY ->\n                    replay(paymentId, begin.decision());\n\n            case IN_PROGRESS ->\n                    throw new IllegalStateException(\n                            "Payment confirmation operation is already in progress"\n                    );\n\n            case OUTCOME_UNKNOWN ->\n                    recover(\n                            operation,\n                            paymentId,\n                            idempotencyKey.value(),\n                            begin.requestHash(),\n                            recovery\n                    );\n\n            case NEW ->\n                    completeNewRecoverable(\n                            operation,\n                            paymentId,\n                            idempotencyKey.value(),\n                            begin.requestHash(),\n                            newRequest,\n                            recovery\n                    );\n        };\n    }\n\n    private PaymentConfirmationBankResult completeNew(\n            String operation,\n            PaymentId paymentId,\n            String idempotencyKey,\n            String requestHash,\n            Supplier<PaymentConfirmationBankResult> newRequest\n    ) {\n        try {\n            PaymentConfirmationBankResult result =\n                    Objects.requireNonNull(\n                            newRequest.get(),\n                            "Payment confirmation bank result"\n                    );\n            complete(\n                    operation,\n                    paymentId,\n                    idempotencyKey,\n                    requestHash,\n                    result\n            );\n            return result;\n        } catch (RuntimeException exception) {\n            fail(\n                    operation,\n                    idempotencyKey,\n                    requestHash,\n                    exception\n            );\n            throw exception;\n        }\n    }\n\n    private PaymentConfirmationBankResult completeNewRecoverable(\n            String operation,\n            PaymentId paymentId,\n            String idempotencyKey,\n            String requestHash,\n            Supplier<PaymentConfirmationBankResult> newRequest,\n            Supplier<PaymentConfirmationBankResult> recovery\n    ) {\n        try {\n            PaymentConfirmationBankResult result =\n                    Objects.requireNonNull(\n                            newRequest.get(),\n                            "Payment confirmation bank result"\n                    );\n            complete(\n                    operation,\n                    paymentId,\n                    idempotencyKey,\n                    requestHash,\n                    result\n            );\n            return result;\n        } catch (PaymentConfirmationGateway.OutcomeUnknownException unknown) {\n            transactions.markOutcomeUnknown(\n                    operation,\n                    idempotencyKey,\n                    requestHash,\n                    paymentId.value(),\n                    unknown.recoveryReference(),\n                    unknown.getMessage(),\n                    timeProvider.now()\n            );\n            return recover(\n                    operation,\n                    paymentId,\n                    idempotencyKey,\n                    requestHash,\n                    recovery\n            );\n        } catch (RuntimeException exception) {\n            fail(\n                    operation,\n                    idempotencyKey,\n                    requestHash,\n                    exception\n            );\n            throw exception;\n        }\n    }\n\n    private PaymentConfirmationBankResult recover(\n            String operation,\n            PaymentId paymentId,\n            String idempotencyKey,\n            String requestHash,\n            Supplier<PaymentConfirmationBankResult> recovery\n    ) {\n        PaymentConfirmationBankResult result =\n                Objects.requireNonNull(\n                        recovery.get(),\n                        "Payment confirmation recovery result"\n                );\n\n        complete(\n                operation,\n                paymentId,\n                idempotencyKey,\n                requestHash,\n                result\n        );\n        return result;\n    }\n\n    private void complete(\n            String operation,\n            PaymentId paymentId,\n            String idempotencyKey,\n            String requestHash,\n            PaymentConfirmationBankResult result\n    ) {\n        transactions.complete(\n                operation,\n                idempotencyKey,\n                requestHash,\n                paymentId.value(),\n                result.status().name(),\n                replayCodec.encode(result),\n                timeProvider.now()\n        );\n    }\n\n    private void fail(\n            String operation,\n            String idempotencyKey,\n            String requestHash,\n            RuntimeException original\n    ) {\n        try {\n            transactions.fail(\n                    operation,\n                    idempotencyKey,\n                    requestHash,\n                    original.getMessage(),\n                    timeProvider.now()\n            );\n        } catch (RuntimeException persistenceFailure) {\n            original.addSuppressed(persistenceFailure);\n        }\n    }\n\n    private PaymentConfirmationBankResult replay(\n            PaymentId paymentId,\n            PaymentIdempotencyDecision decision\n    ) {\n        if (!paymentId.value().equals(decision.paymentId())) {\n            throw new IllegalStateException(\n                    "Payment confirmation replay Payment ID mismatch"\n            );\n        }\n\n        PaymentConfirmationBankResult result =\n                replayCodec.decode(\n                        decision.responsePayload()\n                );\n\n        if (!result.status()\n                .name()\n                .equals(decision.responseStatus())) {\n            throw new IllegalStateException(\n                    "Payment confirmation replay status mismatch"\n            );\n        }\n\n        return result;\n    }\n}\n')
write_new('backend/payment/src/test/java/com/sixpay/payment/infrastructure/idempotency/PaymentOtpIdempotencyFingerprintSetTest.java', 'package com.sixpay.payment.infrastructure.idempotency;\n\nimport org.junit.jupiter.api.Test;\n\nimport javax.crypto.spec.SecretKeySpec;\nimport java.nio.charset.StandardCharsets;\nimport java.util.List;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nclass PaymentOtpIdempotencyFingerprintSetTest {\n\n    @Test\n    void keepsCurrentFingerprintFirstAndPreviousFingerprintsForReplay() {\n        PaymentOtpIdempotencyFingerprint current =\n                fingerprint("current-key-material-for-lot-1.4");\n        PaymentOtpIdempotencyFingerprint previous =\n                fingerprint("previous-key-material-for-lot-1.4");\n\n        PaymentOtpIdempotencyFingerprintSet set =\n                new PaymentOtpIdempotencyFingerprintSet(\n                        List.of(current, previous)\n                );\n\n        List<String> candidates =\n                set.candidates(\n                        "PAY-01ARZ3NDEKTSV4RRFFQ69G5FAV",\n                        "123456".toCharArray()\n                );\n\n        assertThat(candidates).hasSize(2);\n        assertThat(candidates.get(0))\n                .isEqualTo(\n                        current.fingerprint(\n                                "PAY-01ARZ3NDEKTSV4RRFFQ69G5FAV",\n                                "123456"\n                        )\n                );\n    }\n\n    private static PaymentOtpIdempotencyFingerprint fingerprint(\n            String key\n    ) {\n        return new PaymentOtpIdempotencyFingerprint(\n                new SecretKeySpec(\n                        key.getBytes(StandardCharsets.UTF_8),\n                        PaymentOtpIdempotencyFingerprint.ALGORITHM\n                )\n        );\n    }\n}\n')
write_new('backend/payment/src/test/java/com/sixpay/payment/infrastructure/idempotency/PaymentIdempotencyReplayStoreMatchingHashesTest.java', 'package com.sixpay.payment.infrastructure.idempotency;\n\nimport org.junit.jupiter.api.Test;\nimport org.mockito.Mockito;\n\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Optional;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\nimport static org.mockito.Mockito.when;\n\nclass PaymentIdempotencyReplayStoreMatchingHashesTest {\n\n    @Test\n    void recognizesExistingHashProducedByRetainedHmacKey() {\n        PaymentIdempotencyRepository repository =\n                Mockito.mock(PaymentIdempotencyRepository.class);\n        PaymentIdempotencyReplayStore store =\n                new PaymentIdempotencyReplayStore(repository);\n\n        String oldHash = "a".repeat(64);\n        String currentHash = "b".repeat(64);\n\n        PaymentIdempotencyEntity entity =\n                PaymentIdempotencyEntity.start(\n                        "PAYMENT_CONFIRMATION_VERIFY",\n                        "idem-verify-0001",\n                        oldHash,\n                        Instant.parse("2026-08-30T12:00:00Z")\n                );\n\n        when(repository.findByOperationAndIdempotencyKey(\n                "PAYMENT_CONFIRMATION_VERIFY",\n                "idem-verify-0001"\n        )).thenReturn(Optional.of(entity));\n\n        PaymentIdempotencyReplayStore.MatchingBeginResult result =\n                store.beginMatchingHashes(\n                        "PAYMENT_CONFIRMATION_VERIFY",\n                        "idem-verify-0001",\n                        currentHash,\n                        List.of(currentHash, oldHash),\n                        Instant.parse("2026-08-30T12:01:00Z")\n                );\n\n        assertThat(result.decision().kind())\n                .isEqualTo(\n                        PaymentIdempotencyDecision.Kind.IN_PROGRESS\n                );\n        assertThat(result.requestHash())\n                .isEqualTo(oldHash);\n    }\n\n    @Test\n    void rejectsSameKeyWhenNoSecureFingerprintMatches() {\n        PaymentIdempotencyRepository repository =\n                Mockito.mock(PaymentIdempotencyRepository.class);\n        PaymentIdempotencyReplayStore store =\n                new PaymentIdempotencyReplayStore(repository);\n\n        PaymentIdempotencyEntity entity =\n                PaymentIdempotencyEntity.start(\n                        "PAYMENT_CONFIRMATION_VERIFY",\n                        "idem-verify-0002",\n                        "a".repeat(64),\n                        Instant.parse("2026-08-30T12:00:00Z")\n                );\n\n        when(repository.findByOperationAndIdempotencyKey(\n                "PAYMENT_CONFIRMATION_VERIFY",\n                "idem-verify-0002"\n        )).thenReturn(Optional.of(entity));\n\n        assertThatThrownBy(() ->\n                store.beginMatchingHashes(\n                        "PAYMENT_CONFIRMATION_VERIFY",\n                        "idem-verify-0002",\n                        "b".repeat(64),\n                        List.of("b".repeat(64), "c".repeat(64)),\n                        Instant.parse("2026-08-30T12:01:00Z")\n                )\n        ).isInstanceOf(\n                PaymentIdempotencyConflictException.class\n        );\n    }\n}\n')
write_new('backend/payment/src/test/java/com/sixpay/payment/application/PaymentConfirmationIdempotencyArchitectureTest.java', 'package com.sixpay.payment.application;\n\nimport org.junit.jupiter.api.Test;\n\nimport java.nio.file.Files;\nimport java.nio.file.Path;\n\nimport static org.junit.jupiter.api.Assertions.assertFalse;\nimport static org.junit.jupiter.api.Assertions.assertTrue;\n\nclass PaymentConfirmationIdempotencyArchitectureTest {\n\n    private static final Path MAIN =\n            Path.of("src/main/java/com/sixpay/payment");\n\n    @Test\n    void confirmationServiceRoutesMutationsThroughIdempotencyPort()\n            throws Exception {\n\n        String source = Files.readString(\n                MAIN.resolve(\n                        "application/service/"\n                                + "PaymentConfirmationService.java"\n                )\n        );\n\n        assertTrue(source.contains(\n                "PaymentConfirmationIdempotencyPort"\n        ));\n        assertTrue(source.contains(\n                "idempotencyPort.executeCreate("\n        ));\n        assertTrue(source.contains(\n                "idempotencyPort.executeVerify("\n        ));\n        assertTrue(source.contains(\n                "idempotencyPort.executeReplace("\n        ));\n\n        assertFalse(source.contains(\n                "PaymentAtomicPersistencePort"\n        ));\n    }\n\n    @Test\n    void verifyFingerprintReusesApprovedHmacComponent()\n            throws Exception {\n\n        String source = Files.readString(\n                MAIN.resolve(\n                        "infrastructure/idempotency/"\n                                + "PaymentOtpIdempotencyFingerprintSet.java"\n                )\n        );\n\n        assertTrue(source.contains(\n                "PaymentOtpIdempotencyFingerprint"\n        ));\n        assertFalse(source.contains("MessageDigest"));\n    }\n\n    @Test\n    void recoveryMethodCannotCallOriginalMutationSupplier()\n            throws Exception {\n\n        String source = Files.readString(\n                MAIN.resolve(\n                        "infrastructure/idempotency/"\n                                + "PaymentConfirmationIdempotencyAdapter.java"\n                )\n        );\n\n        int start = source.indexOf(\n                "private PaymentConfirmationBankResult recover("\n        );\n        int end = source.indexOf(\n                "private void complete(",\n                start\n        );\n\n        String recoveryMethod = source.substring(start, end);\n\n        assertTrue(recoveryMethod.contains("recovery.get()"));\n        assertFalse(recoveryMethod.contains("newRequest.get()"));\n    }\n}\n')
replace_once('backend/payment/src/main/java/com/sixpay/payment/infrastructure/idempotency/PaymentIdempotencyReplayStore.java', '    @Transactional(propagation = Propagation.MANDATORY)\n    public void markOutcomeUnknown(\n', '    @Transactional(propagation = Propagation.MANDATORY)\n    public MatchingBeginResult beginMatchingHashes(\n            String operation,\n            String idempotencyKey,\n            String preferredRequestHash,\n            java.util.List<String> acceptedRequestHashes,\n            Instant startedAt\n    ) {\n        validate(operation, idempotencyKey, preferredRequestHash);\n        Objects.requireNonNull(startedAt, "Idempotency start instant");\n\n        if (acceptedRequestHashes == null\n                || acceptedRequestHashes.isEmpty()) {\n            throw new IllegalArgumentException(\n                    "Accepted request hashes must not be empty"\n            );\n        }\n\n        java.util.LinkedHashSet<String> accepted =\n                new java.util.LinkedHashSet<>();\n\n        for (String hash : acceptedRequestHashes) {\n            if (hash == null\n                    || !hash.matches("^[0-9a-f]{64}$")) {\n                throw new IllegalArgumentException(\n                        "Accepted request hash is invalid"\n                );\n            }\n            accepted.add(hash);\n        }\n\n        if (!accepted.contains(preferredRequestHash)) {\n            throw new IllegalArgumentException(\n                    "Preferred request hash must be accepted"\n            );\n        }\n\n        Optional<PaymentIdempotencyEntity> existing =\n                repository.findByOperationAndIdempotencyKey(\n                        operation,\n                        idempotencyKey\n                );\n\n        if (existing.isEmpty()) {\n            repository.saveAndFlush(\n                    PaymentIdempotencyEntity.start(\n                            operation,\n                            idempotencyKey,\n                            preferredRequestHash,\n                            startedAt\n                    )\n            );\n\n            return new MatchingBeginResult(\n                    PaymentIdempotencyDecision.newRequest(),\n                    preferredRequestHash\n            );\n        }\n\n        PaymentIdempotencyEntity entity = existing.orElseThrow();\n\n        if (!accepted.contains(entity.requestHash())) {\n            throw new PaymentIdempotencyConflictException(\n                    operation,\n                    idempotencyKey\n            );\n        }\n\n        PaymentIdempotencyDecision decision =\n                switch (entity.status()) {\n                    case COMPLETED ->\n                            PaymentIdempotencyDecision.replay(entity);\n                    case IN_PROGRESS ->\n                            PaymentIdempotencyDecision.inProgress();\n                    case OUTCOME_UNKNOWN ->\n                            PaymentIdempotencyDecision.outcomeUnknown(entity);\n                    case FAILED -> {\n                        entity.restart(startedAt);\n                        repository.saveAndFlush(entity);\n                        yield PaymentIdempotencyDecision.newRequest();\n                    }\n                };\n\n        return new MatchingBeginResult(\n                decision,\n                entity.requestHash()\n        );\n    }\n\n    public record MatchingBeginResult(\n            PaymentIdempotencyDecision decision,\n            String requestHash\n    ) {\n        public MatchingBeginResult {\n            Objects.requireNonNull(decision, "Idempotency decision");\n            if (requestHash == null\n                    || !requestHash.matches("^[0-9a-f]{64}$")) {\n                throw new IllegalArgumentException(\n                        "Effective request hash is invalid"\n                );\n            }\n        }\n    }\n\n    @Transactional(propagation = Propagation.MANDATORY)\n    public void markOutcomeUnknown(\n')
